// Run Configuration - the single place to control this workflow run.
// Edit the values below (or replace this Code node with a Set node) - no other
// node in this workflow should need editing to change these.
const config = {
  as_of_date: '',              // '' = use today (Australia/Melbourne); or 'YYYY-MM-DD' to pin a date
  store: 'Pearcedale',
  data_source: 'SAMPLE',       // SAMPLE | LOCAL_DATASET | SMARTRETAIL
  expected_sku_count: 99,
  // Only used when data_source = 'LOCAL_DATASET': the cloudflared tunnel URL
  // currently pointing at `python model_testing/api.py`'s /local-dataset endpoint.
  local_dataset_api_url: 'https://REPLACE-WITH-YOUR-TUNNEL-URL/local-dataset'
};

const parts = new Intl.DateTimeFormat('en-US', {timeZone:'Australia/Melbourne', year:'numeric', month:'2-digit', day:'2-digit'}).formatToParts(new Date());
const d = Object.fromEntries(parts.map(p => [p.type, p.value]));
const today = `${d.year}-${d.month}-${d.day}`;

const as_of_date = /^\d{4}-\d{2}-\d{2}$/.test(config.as_of_date) ? config.as_of_date : today;

const validSources = ['SAMPLE', 'LOCAL_DATASET', 'SMARTRETAIL'];
if (!validSources.includes(config.data_source)) {
  throw new Error(`data_source must be one of ${validSources.join(', ')}, got '${config.data_source}'`);
}
if (config.data_source === 'LOCAL_DATASET' && !/^https:\/\//.test(config.local_dataset_api_url)) {
  throw new Error('Set local_dataset_api_url to your cloudflared tunnel URL before running LOCAL_DATASET mode');
}

return [{json: {
  as_of_date,
  store: config.store,
  data_source: config.data_source,
  expected_sku_count: config.expected_sku_count,
  local_dataset_api_url: config.local_dataset_api_url,
  mode: 'SAMPLE_TEST',
  live_data_ready: false,
  po_submission_allowed: false
}}];

const r=$input.first().json;
if(r.mode!=='SAMPLE_TEST' || r.po_submission_allowed!==false) throw new Error('This template only permits sample testing. Configure and validate live data and PO rules before enabling a live path.');
return [{json:r}];

// SMARTRETAIL is not implemented. API contracts, credentials, and field
// mappings are not available yet (see model_testing/PO_PROJECT_WORKFLOW.md).
// This branch intentionally fails closed instead of returning invented data.
throw new Error('data_source=SMARTRETAIL is a future placeholder only. Set Run Configuration.data_source to SAMPLE or LOCAL_DATASET.');

const resp = $input.first().json;
const runContext = $('Run Configuration').first().json;
const asOf = runContext.as_of_date;

if (resp.error || !Array.isArray(resp.sales)) {
  return [{json: {
    as_of_date: asOf, data_source: 'LOCAL_DATASET', sku_count: 0,
    records: [], sales_history: [], promotions_history: [],
    fetch_error: String(resp.error?.message || resp.error || 'Local dataset endpoint returned no sales history')
  }}];
}

// The model needs the raw daily history (sales_history/promotions_history) to
// build lag/rolling features - a single snapshot cannot drive it. That history
// is passed through to Modal largely unchanged. For per-SKU business-rule DQ
// (missing supplier/MOQ/lead time etc.) we still derive one canonical latest-
// row-per-SKU snapshot below, same schema/rules as before, from the same data.
const salesHistory = resp.sales;
const promoHistory = Array.isArray(resp.promotions) ? resp.promotions : [];

const latestPromoBySku = new Map();
for (const p of promoHistory) {
  const prev = latestPromoBySku.get(p.itemCode);
  if (!prev || p.trading_date > prev.trading_date) latestPromoBySku.set(p.itemCode, p);
}
const latestSalesBySku = new Map();
for (const s of salesHistory) {
  if (s.trading_date > asOf) continue; // promo history extends into the horizon; sales must not
  const prev = latestSalesBySku.get(s.itemCode);
  if (!prev || s.trading_date > prev.trading_date) latestSalesBySku.set(s.itemCode, s);
}

const records = [...latestSalesBySku.values()].map(r => {
  const missing_fields = [];
  const nullMissing = (name) => { missing_fields.push(name); return null; };
  const promo = latestPromoBySku.get(r.itemCode);

  const daysSince = Math.round((Date.parse(asOf) - Date.parse(r.trading_date)) / 86400000);
  let source_freshness;
  if (Number.isNaN(daysSince)) source_freshness = 'UNKNOWN';
  else if (daysSince <= 1) source_freshness = 'FRESH';
  else if (daysSince <= 7) source_freshness = 'RECENT';
  else source_freshness = 'STALE';

  let promotion_status;
  if (!promo) { nullMissing('promotion_status'); promotion_status = 'UNKNOWN'; }
  else if (promo.promo_active === true) promotion_status = 'ACTIVE';
  else promotion_status = 'NONE';

  return {
    itemCode: r.itemCode ?? null,
    product: nullMissing('product'),
    department: r.departmentName ?? null,
    trading_date: r.trading_date ?? null,
    sales_quantity: r.quantity ?? null,
    qoh: nullMissing('qoh'),
    promotion_status,
    promotion_type: promo?.promo_type_group ?? null,
    discount: promo?.discount_pct ?? null,
    promotion_dates: nullMissing('promotion_dates'),
    supplier_id: r.primarySupplier ?? null,
    moq: r.minOrderQty ?? null,
    carton_quantity: r.cartonQty ?? null,
    open_po_quantity: nullMissing('open_po_quantity'),
    lead_time: nullMissing('lead_time'),
    source_freshness,
    missing_fields,
    days_since_latest_record: Number.isNaN(daysSince) ? null : daysSince
  };
});

return [{json: {
  as_of_date: asOf, data_source: 'LOCAL_DATASET',
  sku_count: records.length, records,
  sales_history: salesHistory, promotions_history: promoHistory,
  fetch_error: null
}}];

const input = $input.first().json;
const runContext = $('Run Configuration').first().json;

if (input.fetch_error) {
  return [{json: {
    as_of_date: input.as_of_date, data_source: input.data_source,
    dq_summary: {total: 0, has_error: true, has_warning: false, has_unknown: false,
      duplicate_skus: [], coverage_issues: [input.fetch_error]},
    dq_records: [], sales_history: [], promotions_history: []
  }}];
}

const records = input.records || [];
const expected = runContext.expected_sku_count;
const isFiniteNum = (v) => typeof v === 'number' && Number.isFinite(v);

const seen = new Set();
const dupes = new Set();
const results = [];
let hasError = false, hasWarning = false, hasUnknown = false;

for (const r of records) {
  const issues = [];
  let status = 'VALID';
  const escalate = (level) => {
    if (level === 'ERROR') status = 'ERROR';
    else if (level === 'WARNING' && status !== 'ERROR') status = 'WARNING';
    else if (level === 'UNKNOWN' && status === 'VALID') status = 'UNKNOWN';
  };

  if (!r.itemCode) { issues.push('Missing SKU'); escalate('ERROR'); }
  if (r.itemCode) {
    if (seen.has(r.itemCode)) { issues.push('Duplicate SKU record'); escalate('ERROR'); dupes.add(r.itemCode); }
    seen.add(r.itemCode);
  }

  if (!r.trading_date || !/^\d{4}-\d{2}-\d{2}$/.test(r.trading_date)) {
    issues.push('Invalid or missing trading_date'); escalate('ERROR');
  } else if (r.trading_date > runContext.as_of_date) {
    issues.push('trading_date is after as_of_date (leakage)'); escalate('ERROR');
  }

  if (r.sales_quantity === null || r.sales_quantity === undefined) {
    issues.push('Sales quantity UNKNOWN (no_row_returned != zero)'); escalate('UNKNOWN');
  } else if (!isFiniteNum(r.sales_quantity) || r.sales_quantity < 0) {
    issues.push('Invalid sales_quantity'); escalate('ERROR');
  }

  if (r.qoh === null || r.qoh === undefined) {
    issues.push('QOH UNKNOWN (not present in local dataset)'); escalate('UNKNOWN');
  } else if (!isFiniteNum(r.qoh) || r.qoh < 0) {
    issues.push('Negative/invalid QOH'); escalate('WARNING');
  }

  if (r.promotion_status === 'UNKNOWN') { issues.push('Promotion status UNKNOWN'); escalate('UNKNOWN'); }
  if (r.promotion_status === 'ACTIVE' && !(r.discount > 0)) {
    issues.push('Active promotion without a positive discount value'); escalate('WARNING');
  }
  if (r.discount !== null && r.discount !== undefined && (!isFiniteNum(r.discount) || r.discount < 0 || r.discount > 1)) {
    issues.push('Discount outside expected 0-1 range'); escalate('WARNING');
  }

  if (!r.supplier_id) { issues.push('Missing supplier_id'); escalate('WARNING'); }
  if (r.moq === null || r.moq === undefined || r.moq <= 0) { issues.push('Missing/invalid MOQ'); escalate('WARNING'); }
  if (r.carton_quantity === null || r.carton_quantity === undefined || r.carton_quantity <= 0) {
    issues.push('Missing/invalid carton_quantity'); escalate('WARNING');
  }
  if (r.lead_time === null || r.lead_time === undefined) {
    issues.push('Lead time UNKNOWN (not present in local dataset)'); escalate('UNKNOWN');
  }
  if (r.open_po_quantity === null || r.open_po_quantity === undefined) {
    issues.push('Open PO quantity UNKNOWN (not present in local dataset)'); escalate('UNKNOWN');
  }

  if (r.source_freshness === 'STALE') {
    issues.push(`Source data stale (${r.days_since_latest_record} days old)`); escalate('WARNING');
  }
  if (r.source_freshness === 'UNKNOWN') {
    issues.push('Freshness UNKNOWN - no historical row at or before as_of_date'); escalate('UNKNOWN');
  }

  if (status === 'ERROR') hasError = true;
  else if (status === 'WARNING') hasWarning = true;
  else if (status === 'UNKNOWN') hasUnknown = true;

  results.push({itemCode: r.itemCode, dq_status: status, dq_issues: issues, record: r});
}

const coverageIssues = [];
if (typeof expected === 'number' && records.length !== expected) {
  coverageIssues.push(`Expected ${expected} SKUs, got ${records.length}`);
}

return [{json: {
  as_of_date: input.as_of_date, data_source: input.data_source,
  dq_summary: {
    total: results.length, has_error: hasError,
    has_warning: hasWarning || coverageIssues.length > 0, has_unknown: hasUnknown,
    duplicate_skus: [...dupes], coverage_issues: coverageIssues
  },
  dq_records: results,
  sales_history: input.sales_history, promotions_history: input.promotions_history
}}];

const r = $input.first().json;
const errors = [];
for (const rec of (r.dq_records || [])) {
  if (rec.dq_status === 'ERROR') errors.push(`${rec.itemCode || 'UNKNOWN_SKU'}: ${rec.dq_issues.join('; ')}`);
}
if (r.dq_summary?.coverage_issues?.length) errors.push(...r.dq_summary.coverage_issues);
return [{json: {status: 'failed', stage: 'data_quality', errors: errors.length ? errors : ['Data quality check failed'], run_id: null}}];

// Prepare Model Input - builds the model_input payload Modal now accepts for
// data_source=LOCAL_DATASET: raw daily sales + promotion history, enough for
// Modal to rebuild the same lag/rolling/promo features preprocess_features.py
// builds for the bundled data. Modal never falls back to bundled data for
// LOCAL_DATASET - missing/invalid model_input is a hard error there.
const dq = $input.first().json;
const runContext = $('Run Configuration').first().json;

return [{json: {
  as_of_date: runContext.as_of_date,
  data_source: runContext.data_source, // 'LOCAL_DATASET'
  token: '10', // Required by current Modal
  model_input: {
    sales: dq.sales_history || [],
    promotions: dq.promotions_history || []
  }
}}];

// Response contract for the current Modal sample endpoint.
// Replace this node only if a future model changes the response schema.
const incoming = $input.first().json;
const expectedDate = $('Run Configuration').first().json.as_of_date;
if (incoming.error || incoming.statusCode >= 400) {
  return [{json: {status: 'failed', stage: 'modal_http',
    errors: [String(incoming.error?.message || incoming.error || `HTTP ${incoming.statusCode}`)]}}];
}
const r = typeof incoming.body === 'string' ? JSON.parse(incoming.body) : (incoming.body || incoming);
if (r?.status === 'error') {
  return [{json: {status: 'failed', stage: 'modal_model', errors: [r.error || 'Model error'], run_id: r.run_id || null}}];
}
const errors = [];
const check = (condition, message) => { if (!condition) errors.push(message); };
const isQty = x => typeof x === 'number' && Number.isFinite(x) && x >= 0;
const f = Array.isArray(r?.forecasts) ? r.forecasts : [];
const p = Array.isArray(r?.recommendations) ? r.recommendations : [];
const summary = r?.summary || {};
check(r?.status === 'passed' && r?.test_type === 'pipeline_smoke_test', 'Unexpected response type');
check(typeof r?.run_id === 'string' && /^[a-f0-9]{32}$/.test(r.run_id), 'Invalid run ID');
check(r?.inventory_is_simulated === true, 'Expected simulated inventory in sample test');
check(summary.run_date === expectedDate, 'As-of date does not match request');
const base = new Date(`${expectedDate}T00:00:00Z`);
const start = new Date(base.getTime() + 86400000).toISOString().slice(0, 10);
const end = new Date(base.getTime() + 15 * 86400000).toISOString().slice(0, 10);
check(summary.horizon?.start === start && summary.horizon?.end === end, 'Incorrect 15-day horizon');
check(f.length > 0 && f.length === summary.total_skus, 'Missing or inconsistent forecasts');
const forecastIds = new Set(f.map(x => x?.itemCode));
check(forecastIds.size === f.length, 'Duplicate forecast SKU');
for (const row of f) {
  check(typeof row?.itemCode === 'string' && row.itemCode.length > 0, 'Missing SKU');
  check(isQty(row?.baseline_forecast_15d) && isQty(row?.hybrid_forecast_15d), 'Invalid forecast demand');
  check(row?.as_of_date === expectedDate && row?.horizon_start === start && row?.horizon_end === end,
    'Incorrect row dates');
}
check(p.length === f.length, 'PO preview coverage does not match forecasts');
const recommendationIds = new Set(p.map(x => x?.itemCode));
check(recommendationIds.size === p.length && [...recommendationIds].every(x => forecastIds.has(x)),
  'Duplicate or unexpected PO preview SKU');
for (const row of p) {
  check(Number.isInteger(row?.recommended_order_qty) && row.recommended_order_qty >= 0,
    'Invalid PO preview quantity');
}
if (errors.length) return [{json: {status: 'failed', stage: 'validation',
  errors: [...new Set(errors)], run_id: r?.run_id || null}}];
return [{json: {
  status: 'passed', mode: 'SAMPLE_TEST', run_id: r.run_id,
  as_of_date: expectedDate, horizon: summary.horizon, total_skus: f.length,
  total_forecast_qty: f.reduce((sum, row) => sum + row.hybrid_forecast_15d, 0),
  simulated_inventory: true, po_submission_allowed: false,
  po_preview_decisions: summary.po_decisions,
  sample_forecasts: f.slice(0, 5), sample_po_preview: p.slice(0, 5),
  warnings: r.warnings || []
}}];
